        talk: '国共内戦で、共産党はなぜ勝てたのでしょうか。大きな理由の一つが、土地です。共産党は支配した村で、地主の土地を取りあげて貧しい農民に分けました。農民たちは、自分の土地を守るために共産党を支えたのです。1949年に中華人民共和国ができると、翌1950年に土地改革法が出され、全国で同じことが行われました。2000年あまり続いた地主と小作人の社会は、こうして終わりをむかえます。',
