    tags: ['tankyu'],
    summary: 'イスラーム国家は征服地の農民から土地税（ハラージュ）をとって軍人や官僚をやしなった。やがて現金の俸給のかわりに、土地からの徴税権を軍人にあたえるイクター制が生まれ、オスマン帝国のティマール制やムガル帝国のマンサブダール制へと受けつがれた。その移り変わりと、近代の土地私有化までをたどる。',
