        talk: '750年、アッバース朝ができると、税のしくみが変わりました。ムスリムであれば、アラブ人もペルシア人も平等。改宗した人は人頭税を払わなくてよくなります。かわりに、アラブ人でも土地を持てば土地税を払います。民族ではなく、信仰と土地にもとづく税です。これが、イスラーム法にもとづく国のかたちでした。762年からは、ティグリス川のほとりに円い城壁の新しい都、バグダードの建設が始まります。',
