        talk: '朝鮮半島では、918年に王建が高麗を建て、やがて半島を統一しました。高麗は976年に田柴科という制度をつくります。官僚の位に応じて、田んぼと、たきぎをとる山林からの収入を受けとる権利をあたえるものです。土地そのものではなく、税を受けとる権利をあたえる点で、イスラーム世界のイクターと似ています。しかし時代がたつと、有力な家が土地を自分のものにしてしまい、制度はくずれていきました。',
