        talk: '224年、イラン人の王朝ササン朝が生まれました。ササン朝は、自分たちこそアケメネス朝の後をつぐ者だと考え、イランの伝統を大切にします。そしてゾロアスター教を国の宗教としました。聖職者の組織がつくられ、長く口で伝えられてきた教えは、アヴェスターという教典にまとめられていきます。ただし、国の宗教が決まると、ほかの宗教への風当たりは強くなります。次に登場するマニは、その犠牲となりました。',
