    summary: '古代オリエントや中国では、馬に引かせる戦車が王や貴族の戦いの主役だった。やがて馬に直接乗り、馬上から弓を射る騎馬遊牧民があらわれると、戦いの主役は騎兵にかわった。農耕国家は遊牧民の戦い方を取りいれ、良い馬を求め、あぶみの発明で騎兵はさらに強くなる。',
