    title: '文字と記録の歴史', period: '前3000年ごろ〜1991年', region: 'west', view: 'world',
    tags: ['tankyu'],
    summary: '文字は、メソポタミア・エジプト・中国でそれぞれ生まれ、国家の支配や信仰、交易の記録に使われた。フェニキア人のアルファベットは西方の文字の祖先となり、中国で生まれた紙と印刷術は世界に広まった。活版印刷は宗教改革や科学革命を支え、20世紀末にはインターネットが情報のあり方を一変させた。',
